import { Component, forwardRef, ChangeDetectionStrategy, ChangeDetectorRef } from '@angular/core';
import { NG_VALUE_ACCESSOR } from '@angular/forms';
import { Type, CronUnixUIService } from '@sbzen/cron-core';

import { CronHostComponent } from './../cron-host.abstract';
import { cronBootstrap5 } from './../styles';

export function bs5UnixCronServiceFactory() {
  return new CronUnixUIService()
};

@Component({
    selector: 'bs5-unix-cron',
    templateUrl: './../unix/unix.html',
    changeDetection: ChangeDetectionStrategy.OnPush,
    providers: [
        {
            provide: CronUnixUIService,
            useFactory: bs5UnixCronServiceFactory
        },
        {
            provide: NG_VALUE_ACCESSOR,
            useExisting: forwardRef(() => Bs5UnixCronComponent),
            multi: true
        }
    ],
    standalone: false
})
export class Bs5UnixCronComponent extends CronHostComponent {
  constructor(
    cd: ChangeDetectorRef,
    cronUnixUI: CronUnixUIService
  ) {
    super(
      cd,
      cronUnixUI,
      [Type.MINUTES, Type.HOURS, Type.DAY, Type.MONTH],
      cronBootstrap5
    );
  }
}

import { Component, Input, Output, EventEmitter, ChangeDetectionStrategy, ChangeDetectorRef } from '@angular/core';
import { Mode } from '@sbzen/cron-core';

import { CronClassesSchema } from './../../styles';

@Component({
    selector: 'cron-and',
    templateUrl: './and.html',
    changeDetection: ChangeDetectionStrategy.OnPush,
    standalone: false
})
export class CronAndComponent {
  @Output() readonly selected = new EventEmitter<void>();
  @Input() checked = false;
  @Input() disabled = false;
  @Input() disabledControls = false;
  @Input() gridSize?: string;
  @Input() label = '';
  @Input() segmentId = '';
  @Input() options: {
    label: string|number,
    value: string
  }[] = [];
  @Input() isValueSelected: (value: string) => boolean = () => false;
  @Input() selectValue: (value: string) => boolean = () => false;
  @Input() schema!: CronClassesSchema;
  readonly mode = Mode.AND;

  constructor(private readonly cd: ChangeDetectorRef) {}

  changeValue(e: Event, value: string) {
    const status = this.selectValue(value);
    if (!status) {
      e.preventDefault();
    }
  }

  detectChanges() {
    this.cd.detectChanges();
  }
}

import { Component, ContentChild, TemplateRef, ChangeDetectionStrategy, Input, ChangeDetectorRef, Output, EventEmitter, ViewChildren, ElementRef, QueryList } from '@angular/core';
import { Type } from '@sbzen/cron-core';

import { CronLocalization } from './../cron-localization';
import { CronClassesSchema } from './../styles';

@Component({
    selector: 'cron-container',
    templateUrl: './container.html',
    styleUrls: ['./container.scss'],
    changeDetection: ChangeDetectionStrategy.OnPush,
    standalone: false
})
export class CronContainerComponent {
  @ContentChild('content') content!: TemplateRef<{ $implicit: Type }>;
  @ViewChildren('tabEl', { read: ElementRef }) tabEls: QueryList<ElementRef>|null = null;
  @Output() readonly tabChanged = new EventEmitter<Type>();
  @Input() localization!: Required<CronLocalization>;
  @Input() hostClass = '';
  @Input() activeTab = Type.MINUTES;
  @Input() tabs: Type[] = [];
  @Input() hideTabs = false;
  @Input() schema!: CronClassesSchema;

  readonly tabsLocalizationKeys = {
    [Type.DAY]: 'day',
    [Type.HOURS]: 'hours',
    [Type.MINUTES]: 'minutes',
    [Type.MONTH]: 'month',
    [Type.SECONDS]: 'seconds',
    [Type.YEAR]: 'year'
  } as const;

  constructor(private readonly cd: ChangeDetectorRef) {}

  navigateTab(code: string, tab: Type) {
    if (!this.tabEls || code !== 'ArrowRight' && code !== 'ArrowLeft') {
      return;
    }
    const tabEls = this.tabEls.toArray().map(er => er.nativeElement);
    const tabs = this.tabs;
    const pos = tabs.indexOf(tab);
    let toPos = 0;

    if (code === 'ArrowRight') {
      const nextPos = pos + 1;
      toPos = (nextPos === tabs.length) ? 0 : nextPos;
    }
    if (code === 'ArrowLeft') {
      const prevPos = pos - 1;
      toPos = (prevPos < 0) ? tabs.length - 1 : prevPos;
    }

    this.setTab(tabs[toPos]);
    const tabEl = tabEls[toPos];
    if (tabEl) {
      tabEl.focus();
      this.cd.detectChanges();
    }
  }

  setTab(tab: Type) {
    this.activeTab = tab;
    this.cd.detectChanges();
    this.tabChanged.emit(tab);
  }
}

import { Component, Input, Output, EventEmitter, ChangeDetectionStrategy } from '@angular/core';
import { Mode } from '@sbzen/cron-core';

import { CronClassesSchema } from './../../styles';

@Component({
    selector: 'cron-every',
    templateUrl: './every.html',
    changeDetection: ChangeDetectionStrategy.OnPush,
    standalone: false
})
export class CronEveryComponent {
  @Output() readonly selected = new EventEmitter<void>();
  @Input() checked = false;
  @Input() disabled = false;
  @Input() label = '';
  @Input() segmentId = '';
  @Input() schema!: CronClassesSchema;

  readonly mode = Mode.EVERY;
}

import { Component, Input, Output, EventEmitter, ChangeDetectionStrategy } from '@angular/core';
import { Mode } from '@sbzen/cron-core';

import { CronClassesSchema } from './../../styles';

@Component({
    selector: 'cron-range',
    templateUrl: './range.html',
    changeDetection: ChangeDetectionStrategy.OnPush,
    standalone: false
})
export class CronRangeComponent {
  @Output() readonly selected = new EventEmitter<void>();
  @Output() readonly primaryValueChanged = new EventEmitter<string>();
  @Output() readonly secondaryValueChanged = new EventEmitter<string>();
  @Input() segmentId = '';
  @Input() checked = false;
  @Input() disabled = false;
  @Input() disabledControls = false;
  @Input() label = '';
  @Input() label2 = '';
  @Input() primaryValue = '';
  @Input() primaryOptions: {
    label: string|number,
    value: string
  }[] = [];
  @Input() secondaryValue = '';
  @Input() secondaryOptions: {
    label: string|number,
    value: string
  }[] = [];
  @Input() schema!: CronClassesSchema;
  readonly mode = Mode.RANGE;

  setPrimaryValue(e: Event) {
    const el = e.target as HTMLSelectElement;
    this.primaryValueChanged.emit(el.value);
